// Step 4, the tip relief: a topping beside each generating crown. A member's tip edges are
// generated by its crown's flanks near their base, the addendum from the pitch line. A topping
// leaves each flank `tip_relief` short of that, at a kink on the flank, turned `relief_angle` so
// the cut widens toward the base, and rounds into a top inside the crown. Swept with the crown, it
// adds only the sliver between topping and flank: each tooth's tip edges chamfered `tip_relief`
// down its flanks. It is a cut of its own, not a kink in the crown's region, because a concave
// corner inside one sweep trims two envelopes against each other (generating-sweep row T2); two
// sweeps meet in the kernel's Boolean instead. Its round and top keep its sheet one smooth chart,
// where a sharp corner would sweep a fan through the blank.
//
// The toppings are the crown's own regions (crown/tooth.sv's `Tooth`, crown/mate.sv's `Space`)
// over cones through the kinks, so their flanks grow nothing: each kink is on its crown's flank as
// grown.
use std
use design
use views
use pitch.gear
use pitch.trace
use pitch.pinion
use crown.thickness
use crown.cutter
use crown.tooth
use crown.mate
use crown.reach
use generation

// Where a topping leaves `flank`, a crown's flank as grown (a side of its region): its `kink` on
// the side's surface in the normal section `n`, at the ordinate `height` along the cutter's `ax`
// from C, beside the pitch point `near`; and the topping's flank, the cone about `ax` through the
// kink leaning `lean`.
component Topping(flank: set, ax: line, n: plane, near: point, height: Length, lean: Angle,
                  design: group) {
  // Seed: along the axis from the pitch point by the kink's height, `ax` the cutter's radius long.
  kink := point hint(at: near, along: ax, by: height / design.cutter_radius) in n
  kink coincident flank.surface
  ax.p1 distance(height, along: ax) kink
  cone := std.ConeThrough(ax, kink, lean: lean)
}

// The pinion's relief beside its crown `tooth` (a Tooth on `cutter`): each flank's topping at
// the kink `tip_relief` above where it generates the pinion's tip edge, the tooth between them from
// the crown's base to a top half an addendum short of the pitch plane.
component ToothRelief(cutter: group, tooth: group, n: plane, inner: point, outer: point,
                      design: group, normal_module: Length) {
  height := design.tip_relief - design.addendum * normal_module
  inner_topping := Topping(tooth.inner, cutter.ax, n, inner, height: height,
    lean: design.pressure + design.shift + design.relief_angle, design: design)
  outer_topping := Topping(tooth.outer, cutter.ax, n, outer, height: height,
    lean: design.shift - design.pressure - design.relief_angle, design: design)
  top := std.Level(cutter.ax.p1, cutter.ax, d: -design.addendum * normal_module / 2)
  relief := crown.tooth.Tooth(inner_topping.cone, outer_topping.cone, cutter.tooth_base, top,
    grow: 0mm, r: design.rounding * normal_module)
}

// The gear's relief beside its space cutter `space` (a Space on `cutter`, closed at `cap` and its
// inner mate turned by `index`): the same, tip down, each kink `tip_relief` below where its flank
// generates the gear's tip edge, the space between them from a top half an addendum short of the
// pitch plane to the mate's base.
component SpaceRelief(cutter: group, space: group, cap: set, index: motion, n: plane,
                      inner: point, outer: point, design: group, normal_module: Length) {
  height := design.addendum * normal_module - design.tip_relief
  outer_topping := Topping(space.inner, cutter.ax, n, outer, height: height,
    lean: design.shift - design.pressure - design.relief_angle, design: design)
  inner_topping := Topping(space.outer, cutter.ax, n, inner, height: height,
    lean: design.pressure + design.shift + design.relief_angle, design: design)
  top := std.Level(cutter.ax.p1, cutter.ax, d: design.addendum * normal_module / 2)
  relief := crown.mate.Space(outer_topping.cone, inner_topping.cone, top, cutter.mate_base, cap,
    index, grow: 0mm, r: design.rounding * normal_module)
}

preview {
  unit mm
  gear := pitch.gear.GearCone(std.top, g.view, design.hypoid_design)
  g := views.FoldedView(std.top, gear.generator)
  trace := pitch.trace.ToothTrace(std.top, gear.generator, design.hypoid_design)
  pinion := pitch.pinion.PinionCone(std.top, q.view, gear, trace.foot, design.hypoid_design)
  q := views.FoldedView(std.top, pinion.hinge)
  thickness := crown.thickness.CrownThickness(std.top, gear.generator, trace.normal,
    design.hypoid_design)
  n := views.FoldedView(std.top, trace.normal)
  cutter := crown.cutter.Cutter(gear.crown_axis, trace.normal, thickness.inner_pitch,
    thickness.outer_pitch, design.hypoid_design, normal_module: trace.normal_module)
  tooth := crown.tooth.Tooth(cutter.inner_flank, cutter.outer_flank, cutter.tooth_base,
    cutter.tooth_tip, grow: design.hypoid_design.backlash / 4,
    r: design.hypoid_design.rounding * trace.normal_module)
  reach := crown.reach.CutterReach(std.top, gear.O, trace.normal, cutter.ax,
    reach: design.hypoid_design.space_reach)
  generation := generation.Generation(gear, pinion, thickness)
  gear_space := crown.mate.Space(cutter.outer_flank, cutter.inner_flank, cutter.mate_tip,
    cutter.mate_base, reach.cap, generation.crown_neighbor,
    grow: design.hypoid_design.backlash / 4, r: design.hypoid_design.rounding * trace.normal_module)
  tooth_relief := ToothRelief(cutter, tooth, n.view, thickness.inner_pitch, thickness.outer_pitch,
    design.hypoid_design, normal_module: trace.normal_module)
  space_relief := SpaceRelief(cutter, gear_space, reach.cap, generation.crown_neighbor, n.view,
    thickness.inner_pitch, thickness.outer_pitch, design.hypoid_design,
    normal_module: trace.normal_module)
}
